18	const INSURANCE_VALUES: Record<string, number> = {
19	  sword: 1000,
20	  amulet: 600,
21	  staff: 800,
22	  potion: 400,
23	  rune: 250,
24	  moonstone: 250,
25	};
26	
27	const DEDUCTIBLE = 100;
28	const CAP_MULTIPLIER = 2;
29	
30	const HIGH_ENCHANTMENT_THRESHOLD = 8;
31	
32	// Per-damage payout: reimbursement clauses (based on the damaged item's
33	// properties) apply to the raw damage amount first, then the flat
34	// deductible is subtracted, floored at 0.
35	const payoutForDamage = (damage: Damage, item: PolicyItem): number => {
36	  const reimbursed =
37	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
38	      ? damage.amount / 2
39	      : damage.amount;
40	  return Math.max(0, reimbursed - DEDUCTIBLE);
41	};
42	
43	export const claim = (
44	  policyItems: PolicyItem[],
45	  damages: Damage[],
46	  priorPayouts: number
47	): ClaimResult => {
48	  const insuranceSum = policyItems.reduce(
49	    (sum, item) => sum + INSURANCE_VALUES[item.type],
50	    0
51	  );
52	  const cap = insuranceSum * CAP_MULTIPLIER;
53	  const totalPayout = damages.reduce((sum, damage) => {
54	    const item = policyItems.find((i) => i.type === damage.itemType)!;
55	    return sum + payoutForDamage(damage, item);
56	  }, 0);
57	  return { payout: totalPayout, remainingCap: cap - priorPayouts - totalPayout };
58	};
