1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface QuoteItem {
6	  type: string;
7	  enchantment?: number;
8	  cursed?: boolean;
9	}
10	
11	export interface QuoteResult {
12	  premium: number;
13	}
14	
15	const BASE_PREMIUMS: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	  moonstone: 25,
22	};
23	
24	const PROCESSING_FEE = 5;
25	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
26	const COMPONENT_BLOCK_SIZE = 3;
27	const COMPONENT_BLOCK_PREMIUM = 60;
28	
29	const countByType = (items: QuoteItem[]): Map<string, number> => {
30	  const counts = new Map<string, number>();
31	  for (const item of items) {
32	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
33	  }
34	  return counts;
35	};
36	
37	// A component type (rune/moonstone) prices as a flat block premium when
38	// exactly COMPONENT_BLOCK_SIZE of that type are present; otherwise every
39	// item (component or not) prices per-unit from BASE_PREMIUMS.
40	const basePremiumForTypeCount = (type: string, count: number): number => {
41	  if (COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE) {
42	    return COMPONENT_BLOCK_PREMIUM;
43	  }
44	  return BASE_PREMIUMS[type] * count;
45	};
46	
47	// NOTE: assumes the item's per-unit base price is BASE_PREMIUMS[item.type],
48	// which is true for all currently-tested cases (including lone/non-block
49	// components). This is NOT yet verified for a cursed component that's part
50	// of a priced block-of-3 (block premium is 20/item effective, not 25/item) —
51	// no test covers that combination yet, so this is left as-is pending one.
52	const curseSurcharge = (item: QuoteItem): number =>
53	  item.cursed ? BASE_PREMIUMS[item.type] / 2 : 0;
54	
55	const HIGH_ENCHANTMENT_THRESHOLD = 5;
56	
57	const enchantmentSurcharge = (item: QuoteItem): number =>
58	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
59	    ? (BASE_PREMIUMS[item.type] * 3) / 10
60	    : 0;
61	
62	const LOYALTY_THRESHOLD_YEARS = 2;
63	
64	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
65	const LOYALTY_DISCOUNT_PERCENT = 20;
66	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
67	
68	// All policy-wide percentages are expressed out of 100, consistently, so
69	// they read as directly comparable rates (10%, 20%, 15%) rather than mixed
70	// tenths/hundredths fractions.
71	const percentOf = (percent: number, amount: number): number => (amount * percent) / 100;
72	
73	// Policy-wide modifiers (loyalty, first insurance, follow-up contract) are
74	// all percentages of the pure policy base premium (sum of item base
75	// premiums, before curse/enchantment surcharges), summed together — not
76	// compounded. First-insurance surcharge always applies (per spec, every
77	// item in a quote is treated as first insurance regardless of customer
78	// history); follow-up-contract discount additionally applies whenever this
79	// is not the customer's first quote in the scenario (contractIndex > 0).
80	const policyWideModifiers = (
81	  customer: Customer,
82	  policyBase: number,
83	  contractIndex: number
84	): number => {
85	  const firstInsuranceSurcharge = percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBase);
86	  const loyaltyDiscount =
87	    customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS
88	      ? percentOf(LOYALTY_DISCOUNT_PERCENT, policyBase)
89	      : 0;
90	  const followUpDiscount =
91	    contractIndex > 0 ? percentOf(FOLLOW_UP_DISCOUNT_PERCENT, policyBase) : 0;
92	  return firstInsuranceSurcharge - loyaltyDiscount - followUpDiscount;
93	};
94	
95	export const quote = (
96	  customer: Customer,
97	  items: QuoteItem[],
98	  contractIndex: number
99	): QuoteResult => {
100	  const counts = countByType(items);
101	  let policyBase = 0;
102	  for (const [type, count] of counts) {
103	    policyBase += basePremiumForTypeCount(type, count);
104	  }
105	  // itemLevelSubtotal starts from the pure policy base and adds per-item
106	  // surcharges (curse, enchantment). Separate loop from the block above:
107	  // curse/enchantment surcharges are per-item modifiers, while the loop
108	  // above is inherently per-type-count (block-of-3 pricing can't be
109	  // computed one item at a time). Kept as a direct sum rather than an
110	  // array-of-modifiers + reduce: with just two modifiers, this is lower
111	  // mass AND reads more directly than iterating a modifier array. Revisit
112	  // the array/reduce abstraction if a third per-item modifier appears.
113	  let itemLevelSubtotal = policyBase;
114	  for (const item of items) {
115	    itemLevelSubtotal += curseSurcharge(item) + enchantmentSurcharge(item);
116	  }
117	  // Multiply-then-divide by whole numbers (not `* 1.1`) avoids float
118	  // epsilon errors for the bases seen so far. The subtotal is intentionally
119	  // left as a fraction — per spec, only the final premium is rounded, via
120	  // the single Math.ceil below.
121	  const subtotal =
122	    itemLevelSubtotal + policyWideModifiers(customer, policyBase, contractIndex);
123	  const premium = Math.ceil(subtotal + PROCESSING_FEE);
124	  return { premium };
125	};
