const totalPayout = damages.reduce((sum, damage) => {
  // TODO(validation): `.find(...)` returns undefined when a damage
  // references an item type not present in the policy; the `!` silences
  // TypeScript but does NOT prevent a runtime crash. Per spec, this case
  // (and unknown item types) must be REJECTED with an explicit,
  // intentional validation error — not a bare non-null-assertion crash.
  // Left as-is pending the Red/Green cycle that adds that validation.
  //
  // TODO(multiple items of same type): `.find` returns only the FIRST
  // policy item matching `damage.itemType`. Once tests cover multiple
  // items of the same type (e.g. two swords with two separate sword
  // damages, matched one-to-one), every damage of that type will
  // incorrectly resolve to the same first item. This will need a
  // one-to-one matching strategy (e.g. consuming matched items, or
  // indexed pairing) instead of a plain `.find`.
  const item = policyItems.find((i) => i.type === damage.itemType)!;
  return sum + payoutForDamage(damage, item);
}, 0);

